import subprocess
import os
import sys
import base64
import ctypes
import time
import tkinter as tk
from tkinter import messagebox
import requests

# ===== FORÇAR ADMIN =====
def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except:
        return False

if not is_admin():
    ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, " ".join(sys.argv), None, 1)
    sys.exit()
# ========================

# ===== SEU CHEAT EM BASE64 =====
CHEAT_BASE64 = ""   # COLE AQUI SEU BASE64
# ===============================

# ===== URL DO GIST =====
URL_USUARIOS = "https://gist.githubusercontent.com/m7monteiro/bfa2949d06b09110b61cbbd49dcbf087/raw/clientes.txt"
# =======================

def obter_diretorio_atual():
    if getattr(sys, 'frozen', False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))

def carregar_usuarios_online():
    try:
        timestamp = int(time.time())
        url = f"{URL_USUARIOS}?t={timestamp}"
        headers = {"Cache-Control": "no-cache"}
        resposta = requests.get(url, timeout=10, headers=headers)
        resposta.raise_for_status()
        usuarios = {}
        for linha in resposta.text.splitlines():
            linha = linha.strip()
            if linha and ':' in linha:
                login, senha = linha.split(':', 1)
                usuarios[login.strip().lower()] = senha.strip()
        return usuarios
    except Exception as e:
        messagebox.showerror("Erro", f"Não carregar usuários.\n{e}")
        return None

def extrair_e_executar():
    try:
        pasta = obter_diretorio_atual()
        exe_temp = os.path.join(pasta, "temp_cheat.exe")
        if os.path.exists(exe_temp):
            os.remove(exe_temp)
        dados = base64.b64decode(CHEAT_BASE64)
        with open(exe_temp, "wb") as f:
            f.write(dados)
        subprocess.Popen([exe_temp])
        root.destroy()
    except Exception as e:
        messagebox.showerror("Erro", f"Falha ao iniciar cheat:\n{e}")

def fazer_login():
    login = entry_login.get().strip().lower()
    senha = entry_senha.get().strip()
    if not login or not senha:
        messagebox.showerror("Erro", "Preencha todos os campos!")
        return
    usuarios = carregar_usuarios_online()
    if usuarios is None:
        return
    if login in usuarios and usuarios[login] == senha:
        messagebox.showinfo("Sucesso", f"✅ Bem-vindo, {login}!")
        extrair_e_executar()
    else:
        messagebox.showerror("Erro", "❌ Login ou senha inválidos!")

# ===== INTERFACE =====
root = tk.Tk()
root.title("M7STORE")
root.geometry("400x450")
root.configure(bg="black")
root.resizable(False, False)
root.eval('tk::PlaceWindow . center')

main_frame = tk.Frame(root, bg="black")
main_frame.pack(expand=True, fill="both", padx=25, pady=20)

# "333" grande vermelho
titulo = tk.Label(main_frame, text="333", font=("Impact", 80, "bold"), fg="red", bg="black")
titulo.pack(pady=(10, 5))

# Linha decorativa
linha = tk.Frame(main_frame, height=1, bg="darkred")
linha.pack(fill="x", pady=10)

# Campos de login
label_login = tk.Label(main_frame, text="LOGIN", font=("Arial", 10, "bold"), fg="darkred", bg="black")
label_login.pack(anchor="w", pady=(10, 0))
entry_login = tk.Entry(main_frame, font=("Arial", 11), bg="#1a1a1a", fg="red", insertbackground="red",
                       relief="flat", highlightthickness=1, highlightcolor="red")
entry_login.pack(fill="x", pady=(2, 12))
entry_login.focus()

label_senha = tk.Label(main_frame, text="SENHA", font=("Arial", 10, "bold"), fg="darkred", bg="black")
label_senha.pack(anchor="w", pady=(5, 0))
entry_senha = tk.Entry(main_frame, font=("Arial", 11), bg="#1a1a1a", fg="red", show="•", insertbackground="red",
                       relief="flat", highlightthickness=1, highlightcolor="red")
entry_senha.pack(fill="x", pady=(2, 20))
entry_senha.bind("<Return>", lambda e: fazer_login())

# Botão ENTRAR
btn = tk.Button(main_frame, text="ENTRAR", font=("Arial", 10, "bold"), bg="red", fg="black",
                activebackground="#8b0000", activeforeground="white", relief="flat",
                command=fazer_login)
btn.pack(pady=5, ipadx=15, ipady=3)

# Rodapé com símbolo de copyright
footer = tk.Label(main_frame, text="© M7STORE 2026", font=("Arial", 8, "italic"), fg="#330000", bg="black")
footer.pack(side="bottom", pady=(15, 0))

root.mainloop()
